// src/components/EmployeeForm.jsx
import { useState } from 'react';
import axios from 'axios';

export default function EmployeeForm() {
  const [formData, setFormData] = useState({
    name: '',
    doj: '',
    designation: '',
    salary: ''
  });

  const [pdfUrl, setPdfUrl] = useState(null);

  const handleChange = (e) => {
    setFormData({ ...formData, [e.target.name]: e.target.value });
  };

  const handleSubmit = async (e) => {
  e.preventDefault();
  try {
    const res = await axios.post('http://127.0.0.1:5000/api/generate-pdf', formData, {
      responseType: 'blob'
    });
    const file = new Blob([res.data], { type: 'application/pdf' });
    setPdfUrl(URL.createObjectURL(file));
  } catch (err) {
    alert("Error generating PDF");
  }
};

return (
  <div style={{ maxWidth: "500px", margin: "40px auto", padding: "20px", border: "1px solid #ddd", borderRadius: "10px", fontFamily: "Arial, sans-serif" }}>
    <h2 style={{ textAlign: "center", color: "#333", marginBottom: "30px" }}>
      Onboarding Document Generator
    </h2>
    
    <form onSubmit={handleSubmit}>
      {['name', 'doj', 'designation', 'salary'].map((field) => (
        <div key={field} style={{ marginBottom: "20px" }}>
          <label style={{ display: "block", marginBottom: "8px", fontWeight: "bold", color: "#555", textTransform: "capitalize" }}>
            {field}
          </label>
          <input
            name={field}
            value={formData[field]}
            onChange={handleChange}
            required
            style={{
              width: "100%",
              padding: "10px",
              border: "1px solid #ccc",
              borderRadius: "5px",
              fontSize: "14px"
            }}
          />
        </div>
      ))}

      <button
        type="submit"
        style={{
          width: "100%",
          padding: "12px",
          backgroundColor: "#007bff",
          color: "#fff",
          border: "none",
          borderRadius: "6px",
          fontSize: "16px",
          cursor: "pointer"
        }}
      >
        Generate PDF
      </button>
    </form>

    {pdfUrl && (
      <div style={{ marginTop: "30px", textAlign: "center" }}>
        <a
          href={pdfUrl}
          download="onboarding_bundle.pdf"
          style={{
            color: "#007bff",
            textDecoration: "none",
            fontWeight: "bold"
          }}
        >
          Download PDF
        </a>
      </div>
    )}
  </div>
);

}
